            }
        }
    }
}

.step-navigate-existing-customer{
    display: none;
    max-width: 520px;
}

.step-search-by-info{
    display: none;
    max-width: 520px;
}

.step-search-by-orderNumber{
    display: none;
    max-width: 520px;
}

.step-search-result{
    display: none;
    max-width: 520px;
    h3{
        margin: 0;
    }
    .result-count{
        font-size: 14px;
        font-weight: 400;
        line-height: 22px;
        text-align: left;
        margin: 0 0 20px 0;
    }
    .bc-auth-compnay-lists{
        width: 100%;
        .bc-auth-compnay-list{
            width: 100%;
            padding: 10px 10px 10px 45px;
            border: 1px solid #CCCCCC;
            border-radius: 8px;
            margin: 0 0 15px 0;
            cursor: pointer;
            font-size: 14px;
            font-weight: 400;
            line-height: 22px;
            text-align: left;
            position: relative;
            user-select: none;

            &::before{
                content: '';
                width: 15px;
                height: 15px;
                border:1px solid #CCCCCC;
                position: absolute;
                left: 15px;
                top: 15px;
                border-radius: 50%;
            }

            &.is-active{
                &::before{
                    border:1px solid #000000;
                }
                &::after{
                    content: '';
                    width: 9px;
                    height: 9px;
                    background: #000000;
                    border: 1px solid #000000;
                    position: absolute;
                    left: 17.5px;
                    top: 17.5px;
                    border-radius: 50%;
                }
            }

            &:hover, &.is-active{
                border: 1px solid #005AAF;
            }
        }
    }
}


